def transform_per_cell_nearest(grid):
    """Each '1' independently becomes its nearest non-zero, non-1 color"""
    result = [[0] * len(grid[0]) for _ in range(len(grid))]

    h, w = len(grid), len(grid[0])
    def nearest(pos):
        r, c = pos
        min_d = float('inf')
        best = None
        for i in range(h):
            for j in range(w):
                v = grid[i][j]
                if v != 0 and v != 1:
