def solve_demo2_nearest():
    # Build color regions
    color_cells = {v: [(r,c) for r in range(9) for c in range(9) 
                       if demo2_in[r][c] == v] for v in [6,7,9]}

    # Find components
    visited = [[False]*9 for _ in range(9)]
    comps = []
    for r in range(9):
        for c in range(9):
            if demo2_in[r][c] == 1 and not visited[r][c]:
                comp = []
                q = [(r,c)]
                visited[r][c] = True
                while q:
                    cr, cc = q.pop(0)
                    comp.append((cr,cc))
                    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr,nc = cr+dr, cc+dc
                        if 0<=nr<9 and 0<=nc<9 and not visited[nr][nc] and demo2_in[nr][nc]==1:
                            visited[nr][nc]=True
                            q.append((nr,nc))
                comps.append(comp)

    result = [[demo2_in[r][c] for c in range(9)] for r in range(9)]

    # Sort components by top-left
    sorted_comps = sorted(comps, key=lambda c: (c[0][0], c[0][1]))

    def manhattan(p1, p2):
        return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])

    for comp in sorted_comps:
        # Pick first cell of component
        r, c = comp[0]
        min_dist = float('inf')
        best_color = None

        for val in color_cells:
            min_d = float('inf')
            for ir, ic in color_cells[val]:
                d = manhattan((r,c), (ir,ic))
                if d < min_d:
                    min_d = d
            if min_d < min_dist:
                min_dist = min_dist
                best_color = val
            elif min_d == min_dist and (best_color is None or val < best_color):
                best_color = val

        for rr, cc in comp:
            result[rr][cc] = best_color

    print("Nearest Prediction:")
    for row in result:
        print(row)

    print("\nExpected:")
    for row in demo2_out:
        print(row)

    match = all(result[r][c] == demo2_out[r][c] for r in range(9) for c in range(9))
    print(f"\nMatch: {match}")

